// Проверка запроса и сборка задания для модели.
//
// Гид отвечает ТОЛЬКО по тому тексту, который человек уже видит на экране.
// Это главное правило: если разрешить ему отвечать из собственной памяти,
// приложение превратится в «спроси у модели», а проверенный справочник
// станет не нужен. И модель начнёт врать про даты — ровно то, чего
// Алексей просил не допустить.

const body = $input.first().json.body ?? $input.first().json;

const intent = String(body.intent ?? 'explain');
const lang = String(body.lang ?? 'ru');
const subject = String(body.subject ?? '').slice(0, 200);
const material = String(body.material ?? '').slice(0, 2500);

if (!subject || !material) {
  return [{ json: { bad: true, reason: 'пустой запрос' } }];
}

const tasks = {
  explain: 'Объясни это проще, как будто рассказываешь человеку, который слышит про это впервые. Никакого жаргона.',
  why: 'Объясни, почему это важно и как это связано с сегодняшним днём.',
  next: 'Подскажи, что логично посмотреть дальше, и коротко скажи почему. Предлагай только то, что упомянуто в тексте.',
};

const rules = [
  'Ты гид внутри приложения по истории. Твоя работа — помочь понять то, что человек уже открыл.',
  'Опирайся ТОЛЬКО на текст ниже. Если в нём нет ответа, честно скажи: «в этой карточке об этом не сказано».',
  'НЕ называй дат, имён и чисел, которых нет в тексте. Вообще никаких. Это важнее, чем полнота ответа.',
  'Отвечай на языке с кодом ' + lang + '.',
  'Три-четыре предложения, не больше. Простыми словами.',
].join('\n');

const prompt = rules + '\n\nЗАДАНИЕ: ' + (tasks[intent] ?? tasks.explain) +
  '\n\nО ЧЁМ: ' + subject + '\n\nТЕКСТ:\n' + material;

return [{ json: { prompt, lang, subject } }];

// Ответ приложению. Поле app обязательно: приложение отказывается
// показывать неподписанный ответ.
//
// Так поймана давняя беда NEXUS: там адрес указывал на воркфлоу другого
// приложения, и «наставник по коду» учил инвестициям. Подпись делает
// такую подмену видимой сразу.

const raw = $input.first().json;
const answer = raw?.candidates?.[0]?.content?.parts?.[0]?.text ?? '';

return [{
  json: {
    app: 'atlas',
    answer: String(answer).trim().slice(0, 900),
  },
}];
